WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_basic_expression'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '语言表达与流畅度', 'kp-ms-basic-expression', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "语言表达与流畅度"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "流畅大于华丽。消除口头禅是第一要务。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、致命雷区（口头禅）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“然后”、“就是”、“那什么”、“嗯”：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "这些高频口头禅会极大拉低你的气场。训练方法：用录音笔录下自己的答题，强制用“第一、第二”、“因此”、“综上所述”等连接词替换掉无意义的口头禅。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、降速求稳"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "面试紧张时语速会不自觉加快。语速过快容易导致大脑当机卡壳。刻意将语速降到平时的 80%，在每个层级之间留出 1-2 秒的停顿，不仅显得稳重，还能给大脑思考下一句争取时间。"}]}]}$$ AS jsonb), NULL, '语言表达与流畅度的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "基础素养", "语言表达"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_basic_expression", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
